CREATE DATABASE IF NOT EXISTS tecnico_ya CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE tecnico_ya;
CREATE TABLE IF NOT EXISTS users(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('ADMIN','GESTOR','TECNICO','CLIENTE') NOT NULL,phone VARCHAR(30),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS technicians(user_id BIGINT PRIMARY KEY, specialty VARCHAR(100) NOT NULL,zone VARCHAR(100) NOT NULL,available BOOLEAN DEFAULT TRUE,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS services(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,description TEXT,active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS requests(id BIGINT AUTO_INCREMENT PRIMARY KEY,client_id BIGINT NOT NULL,service_id BIGINT NOT NULL,description TEXT NOT NULL,address VARCHAR(250) NOT NULL,comuna VARCHAR(120) NOT NULL,contact_phone VARCHAR(30) NOT NULL,preferred_date DATE NULL,status ENUM('PENDIENTE','REVISADA','CONVERTIDA','CANCELADA') NOT NULL DEFAULT 'PENDIENTE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(client_id) REFERENCES users(id),FOREIGN KEY(service_id) REFERENCES services(id));
CREATE TABLE IF NOT EXISTS orders(id BIGINT AUTO_INCREMENT PRIMARY KEY,request_id BIGINT NOT NULL UNIQUE,technician_id BIGINT NULL,status ENUM('PENDIENTE','ASIGNADA','EN_PROCESO','FINALIZADA','CANCELADA') NOT NULL DEFAULT 'PENDIENTE',start_code_hash VARCHAR(255),end_code_hash VARCHAR(255),start_code_used BOOLEAN DEFAULT FALSE,end_code_used BOOLEAN DEFAULT FALSE,started_at DATETIME NULL,finished_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(request_id) REFERENCES requests(id),FOREIGN KEY(technician_id) REFERENCES technicians(user_id));
CREATE TABLE IF NOT EXISTS evidence(id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,technician_id BIGINT NOT NULL,note TEXT,photo_path VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(technician_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit_log(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,order_id BIGINT NULL,action VARCHAR(100) NOT NULL,detail JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
